('SO5.1','SO5.1-P2-03','สังเกตและแสดงความสัมพันธ์ระหว่างโลก ดวงอาทิตย์และดวงจันทร์ที่ทำให้เกิดปรากฏการณ์',3,false,'ส ๔.๑ ป.๒/๓ (ตารางภูมิศาสตร์; จัดเข้ามาตรฐาน SO5.1)'),
('SO5.2','SO5.2-P2-01','อธิบายความสำคัญของสิ่งแวดล้อมทางธรรมชาติและที่มนุษย์สร้างขึ้น',1,true,'ส ๔.๒ ป.๒/๓ (ตารางภูมิศาสตร์; จัดเข้ามาตรฐาน SO5.2)'),
('SO5.2','SO5.2-P2-02','จำแนกและใช้ทรัพยากรธรรมชาติที่ใช้แล้วไม่หมดไป ที่ใช้แล้วหมดไป และสร้างทดแทนขึ้นใหม่ได้อย่างคุ้มค่า',2,false,'ส ๔.๒ ป.๒/๒ (ตารางภูมิศาสตร์; จัดเข้ามาตรฐาน SO5.2)'),
('SO5.2','SO5.2-P2-03','อธิบายความสัมพันธ์ระหว่างฤดูกาล กับการดำเนินชีวิตของมนุษย์',3,true,'ส ๔.๒ ป.๒/๓ (ตารางภูมิศาสตร์; จัดเข้ามาตรฐาน SO5.2)'),
('SO5.2','SO5.2-P2-04','มีส่วนร่วมในการจัดการสิ่งแวดล้อมในโรงเรียน',4,true,'ส ๔.๒ ป.๒/๔ (ตารางภูมิศาสตร์; จัดเข้ามาตรฐาน SO5.2)')
)
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes)
select o.id,c.id,gl.id,seed.sequence_no,seed.is_required,
 'OBEC 2021 classification: '||case when seed.is_required then 'must know' else 'should know' end||'; source code '||seed.source_indicator_code
from seed join public.learning_topics t on t.code=seed.standard_code
join public.learning_skills sk on sk.id=t.skill_id join public.learning_subjects s on s.id=sk.subject_id and s.code='SOCIAL-STUDIES'
join public.learning_objectives o on o.topic_id=t.id and o.code=seed.objective_code
join public.learning_curricula c on c.code='TH-BASIC-CORE-2008-2017'
join public.learning_grade_levels gl on gl.curriculum_id=c.id and gl.code='P2'
on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,notes=excluded.notes,updated_at=now();
